let order=false,ticket='absent',copies=0,delivered=0,shipments=0,seen=false,ack=false;
function paint(){dbView.textContent=`A100: ${order?'saved':'absent'} · E7: ${ticket}`;brokerView.textContent=`${copies} copies of E7`;shipView.textContent=`${shipments} shipments · E7 marker: ${seen?'saved':'absent'}`;}
function tell(s){world.textContent=s;paint();}
saveOrder.onclick=()=>{if(order)return tell('A100 is already saved. Reset to start again.');order=true;ticket='pending';tell('Both rows committed together. A crash now cannot erase the waiting ticket.');};
sendEvent.onclick=()=>{if(ticket!=='pending')return tell('No pending ticket to send.');copies++;ack=true;tell('Kafka accepted E7. The ticket still says pending until step 3.');};
markSent.onclick=()=>{if(!ack)return tell('No send acknowledgement in this relay session. Send first.');ticket='sent';tell('The relay recorded success.');};
crashRelay.onclick=()=>{ack=false;tell('Relay memory lost. The three saved states survive. A pending ticket can be sent again.');};
deliver.onclick=()=>{while(delivered<copies){if(!dedup.checked||!seen){shipments++;if(dedup.checked)seen=true;}delivered++;}tell('Consumer processed the queued copies. Compare copies with shipments.');};
resetLab.onclick=()=>{order=false;ticket='absent';copies=delivered=shipments=0;seen=ack=false;tell('Empty systems. Start with Save order.');};resetLab.onclick();

function drawMechanism(){let events='';for(let i=0;i<copies;i++)events+='<div class="arrowpath">Kafka copy '+(i+1)+': <strong>E7</strong> → '+(i<delivered?'consumed':'waiting for consumer')+'</div>';mechanismView.innerHTML='<div style="border:2px solid #8ed4b0;padding:12px"><strong>One database commit boundary</strong><p>Order A100: '+(order?'SAVED':'absent')+'<br>Outbox E7: '+ticket+'</p></div><p>Saved outbox → relay sends → Kafka receives a copy</p><p>Relay memory only: send acknowledgement <strong>'+(ack?'present':'absent')+'</strong>. Crash clears this memory, not saved rows.</p>'+(events||'<p>No Kafka copy yet.</p>')+'<p>Consumer → '+(dedup.checked?'check saved E7 marker → create shipment only if new':'NO event-identity check → each consumed copy creates a shipment')+'</p><div style="border:2px solid #8ed4b0;padding:12px"><strong>Shipping database commit boundary</strong><p>E7 marker: '+(seen?'SAVED':'absent')+'<br>Shipments: '+shipments+'</p></div><p class="note">The earlier summary boxes and this ledger show the same state. Pending means “not recorded as sent,” not “never sent.” Turning deduplication on after an unprotected effect does not repair the past.</p>';}

const basePaint=paint;paint=function(){basePaint();drawMechanism();};paint();

let state='closed',failures=0,forwarded=0,blocked=0,clock=0,reopenAt=0;
function paint(){closedCard.className='tile '+(state==='closed'?'active':'');openCard.className='tile '+(state==='open'?'active':'');probeCard.className='tile '+(state==='half-open'?'active':'');counts.textContent=`Time ${clock}s · Forwarded ${forwarded} · Blocked ${blocked} · Consecutive failures ${failures}`;}
callService.onclick=()=>{if(state==='open'&&clock<reopenAt){blocked++;world.textContent='Blocked here. No call reached the service.';}else{if(state==='open')state='half-open';forwarded++;if(healthy.checked){failures=0;state='closed';world.textContent='Call succeeded. Normal calls are allowed.';}else{failures++;if(state==='half-open'||failures>=3){state='open';reopenAt=clock+5;world.textContent='Call failed. Breaker opens for 5 seconds.';}else world.textContent='Call reached the service and failed.';}}paint();};
advance.onclick=()=>{clock+=5;if(state==='open'&&clock>=reopenAt){state='half-open';world.textContent='Waiting period ended. The next call is a probe.';}else world.textContent='Clock advanced. No call was sent.';paint();};
resetLab.onclick=()=>{state='closed';failures=forwarded=blocked=clock=reopenAt=0;healthy.checked=false;world.textContent='Service is down. Send calls to see the breaker react.';paint();};resetLab.onclick();

function drawMechanism(){const s=state;const box=(y,label,active)=>'<rect x="78" y="'+y+'" width="234" height="45" rx="7" fill="'+(active?'#397852':'#24434a')+'" stroke="'+(active?'#ffd08a':'#8ca6ab')+'" stroke-width="2"/><text x="195" y="'+(y+28)+'" text-anchor="middle" font-size="18">'+label+'</text>';mechanismView.innerHTML='<svg viewBox="0 0 390 310" role="img" aria-label="Current circuit state '+s+'"><path d="M195 57 V107 M195 152 V203 M313 224 H367 V35 H313 M78 224 H25 V131 H78" fill="none" stroke="#adc8ca" stroke-width="2"/>'+box(12,'CLOSED · calls pass',s==='closed')+box(107,'OPEN · calls blocked',s==='open')+box(203,'HALF-OPEN · one probe',s==='half-open')+'<text x="195" y="82" text-anchor="middle" font-size="14">3 failures ↓</text><text x="195" y="180" text-anchor="middle" font-size="14">wait 5 seconds ↓</text><text x="360" y="194" transform="rotate(-90 360 194)" font-size="14">probe success → close</text><text x="22" y="281" font-size="14">Failed probe returns to OPEN via left path.</text></svg><div class="arrowpath">Checkout call → breaker ['+s+'] → '+(s==='open'&&clock<reopenAt?'STOP here · dependency receives nothing':(s==='half-open'?'one probe → ':'')+'delivery service '+(healthy.checked?'HEALTHY':'DOWN'))+'</div><p>Until next permitted probe: <strong>'+Math.max(0,reopenAt-clock)+' s</strong>. Calls reaching dependency: '+forwarded+'; stopped before dependency: '+blocked+'.</p>';}

const basePaint=paint;paint=function(){basePaint();drawMechanism();};paint();

function paint(){oldRoutes.textContent=moveTracking.checked?'/orders, /returns':'/orders, /tracking, /returns';newRoutes.textContent=moveTracking.checked?'/tracking':'No customer routes';}
function request(route){const owner=route==='/tracking'&&moveTracking.checked?'new':'old';const ok=route!=='/tracking'||(owner==='new'?newHealthy.checked:oldCompatible.checked);world.textContent=`${route} → ${owner} system → ${ok?'A100 response returned':'FAILED: '+(owner==='new'?'new service unavailable':'old reader cannot read current data')}`;}
moveTracking.onchange=()=>{paint();world.textContent='Ownership changed. Send a request to test it.';};newHealthy.onchange=oldCompatible.onchange=()=>{world.textContent='Assumption changed. Send a request to see its effect.';};requestOrders.onclick=()=>request('/orders');requestTracking.onclick=()=>request('/tracking');requestReturns.onclick=()=>request('/returns');paint();world.textContent='All routes begin with the old system.';

let lastRoute='';
function drawMechanism(){const paths=['/orders','/tracking','/returns'];mechanismView.innerHTML='<p><strong>Same customer entry point → router → one owner per route</strong></p><table><thead><tr><th>Request path</th><th>Owner</th><th>Can it answer?</th></tr></thead><tbody>'+paths.map(r=>{const neo=r==='/tracking'&&moveTracking.checked,ok=r!=='/tracking'||(neo?newHealthy.checked:oldCompatible.checked);return '<tr style="'+(lastRoute===r?'outline:2px solid #ffd08a;':'')+'"><th>'+r+(lastRoute===r?' ← sent':'')+'</th><td>→ '+(neo?'NEW':'OLD')+'</td><td>'+(ok?'✓ A100 readable':'✕ '+(neo?'service unavailable':'data incompatible'))+'</td></tr>';}).join('')+'</tbody></table><p>/orders remains the old system’s write responsibility in this example. Moving /tracking changes its route owner, not the stored data.</p><p class="note">A failed new service can be routed back only if the old reader remains compatible. Request success assumes the other simplified dependencies work.</p>';}
const basePaint=paint;paint=function(){basePaint();drawMechanism();};const baseRequest=request;request=function(route){lastRoute=route;baseRequest(route);drawMechanism();};newHealthy.onchange=oldCompatible.onchange=()=>{world.textContent='Assumption changed. Send a request to see its effect.';drawMechanism();};paint();

let proposedOrder='A100',amount=25,balance=5000,done=false;
function gates(){return [Number.isInteger(amount)&&amount>0,proposedOrder==='A100'&&amount===2500,proposedOrder==='A100'&&amount<=balance];}
function paint(){const g=gates();proposal.textContent=`Proposal: ${proposedOrder}, amount_cents = ${amount}`;balanceView.textContent=`${balance} cents`;shapeGate.textContent=`${g[0]?'PASS':'STOP'} · Shape: positive integer`;intentGate.textContent=`${g[1]?'PASS':'STOP'} · Intent: A100 and 2500 cents`;permissionGate.textContent=`${g[2]?'PASS':'STOP'} · Permission/state: owned order and sufficient balance`;}
function choose(o,a){proposedOrder=o;amount=a;paint();world.textContent='Checked only. No refund has run.';}
wrongUnits.onclick=()=>choose('A100',25);correctInput.onclick=()=>choose('A100',2500);wrongOrder.onclick=()=>choose('B200',2500);negativeInput.onclick=()=>choose('A100',-10);
execute.onclick=()=>{if(done){world.textContent='This approved action already ran. No second refund.';return;}if(!gates().every(Boolean)){world.textContent='Blocked. At least one required check failed.';return;}balance-=amount;done=true;paint();world.textContent='Mock refund ran once: 2500 cents refunded.';};
resetLab.onclick=()=>{balance=5000;done=false;choose('A100',25);};resetLab.onclick();

function drawMechanism(){const g=gates(),stop=g.findIndex(v=>!v),labels=['positive integer','matches A100 / 2500 cents','owned A100 and enough balance'];const bar=(label,n,color)=>'<p>'+label+': '+n+' cents</p><div class="band"><span style="width:'+Math.max(0,Math.min(100,n/50))+'%;background:'+color+'"></span></div>';mechanismView.innerHTML=bar('Trusted requested refund',2500,'#397852')+bar('Proposed refund',amount,'#c9954f')+'<p>Both amount bars: 0–5,000 cents. Negative proposals have no positive bar and fail the shape check.</p><ol>'+labels.map((label,i)=>'<li><strong>'+(g[i]?'PASS':'STOP')+'</strong> '+label+(i===stop?' ← first failed requirement':'')+'</li>').join('')+'</ol><div class="arrowpath">All checks '+(g.every(Boolean)?'pass':'do not pass')+' → '+(done?'action already used → no second refund':g.every(Boolean)?'eligible to execute → press Run mock refund':'blocked before ledger mutation')+'</div>'+bar('Balance remaining',balance,'#5289ab')+'<p>Refund already executed: '+done+'. The balance bar changes only after an allowed execution, not after choosing a proposal.</p>';}

const basePaint=paint;paint=function(){basePaint();drawMechanism();};paint();

let stored=0;
function paint(){requested.textContent=`${level.value} of 15`;storedView.textContent=`${stored} of 15`;levelBar.style.width=(stored/15*100)+'%';readView.textContent=readLight.checked?`Input 0.6 × weight ${(stored/15).toFixed(3)} = ${(0.6*stored/15).toFixed(3)}`:'No optical reading. The level is still stored.';}
level.oninput=()=>{paint();world.textContent='Slider changed the request, not the saved level. Press Program to write.';};
program.onclick=()=>{if(!writePower.checked){world.textContent='Cannot program without programming power. Saved level unchanged.';return;}stored=Number(level.value);paint();world.textContent='Level programmed. Now remove programming power.';};
writePower.onchange=()=>{paint();world.textContent=writePower.checked?'Programming power restored.':'Programming power removed; stored level retained in this ideal model.';};readLight.onchange=()=>{paint();world.textContent='Reading changed, not the stored level.';};paint();world.textContent='Begin by programming level 10.';

function drawMechanism(){const r=+level.value;let ladder='';for(let i=15;i>=0;i--)ladder+='<tr><th>'+i+'</th><td style="background:'+(i===r?'#9b7139':'#10292e')+'">'+(i===r?'REQUEST →':'')+'</td><td style="background:'+(i===stored?'#397852':'#10292e')+'">'+(i===stored?'● STORED':'')+'</td></tr>';mechanismView.innerHTML='<div class="columns"><div><table><thead><tr><th>Level</th><th>Requested</th><th>Saved</th></tr></thead><tbody>'+ladder+'</tbody></table></div><div><div class="arrowpath">Write path: selected '+r+' → '+(writePower.checked?'programming power available → press Program':'POWER OFF → write blocked')+'</div><div class="arrowpath">Hold: saved level <strong>'+stored+'</strong> persists '+(writePower.checked?'with power connected':'with programming power removed')+'</div><div class="arrowpath">Read: input 0.6 → saved weight '+stored+'/15 → '+(readLight.checked?'detector: '+(0.6*stored/15).toFixed(3):'LIGHT/DETECTOR OFF → no measurement')+'</div><p>Requested and saved markers coincide only after a successful write (or if you select the already stored level).</p></div></div><p class="note">This ideal arithmetic model has no retention decay, noise, write fatigue, or device calibration. Stored does not mean readable without energy.</p>';}

const basePaint=paint;paint=function(){basePaint();drawMechanism();};paint();
